import { useMemo, useState } from 'react';
import { JxCalendar, JxChip } from '@jinx-ui/react';

type ReportDatePickerProps = {
  defaultValue?: Date | null;
  locale?: string;
  onChange?: (value: Date | null) => void;
};

const startOfDay = (date: Date) => new Date(date.getFullYear(), date.getMonth(), date.getDate());

const shiftDays = (date: Date, days: number) =>
  new Date(date.getFullYear(), date.getMonth(), date.getDate() + days);

const isSameDay = (a: Date | null, b: Date) =>
  a !== null &&
  a.getFullYear() === b.getFullYear() &&
  a.getMonth() === b.getMonth() &&
  a.getDate() === b.getDate();

export default function ReportDatePicker({
  defaultValue = null,
  locale = 'ru-RU',
  onChange,
}: ReportDatePickerProps) {
  const [value, setValue] = useState<Date | null>(defaultValue);

  const presets = useMemo(() => {
    const today = startOfDay(new Date());
    return [
      { key: 'today', label: 'Сегодня', date: today },
      { key: 'yesterday', label: 'Вчера', date: shiftDays(today, -1) },
      { key: 'week', label: 'Неделя назад', date: shiftDays(today, -7) },
    ];
  }, []);

  const select = (next: Date | null) => {
    setValue(next);
    onChange?.(next);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }} role="group" aria-label="Быстрый выбор даты">
        {presets.map((preset) => (
          <JxChip
            key={preset.key}
            active={isSameDay(value, preset.date)}
            onClick={() => select(preset.date)}
          >
            {preset.label}
          </JxChip>
        ))}
      </div>
      <JxCalendar locale={locale} value={value} onValueChange={select} />
    </div>
  );
}

